1	/// JSON-RPC 2.0 server over stdin/stdout.
2	///
3	/// SECURITY INVARIANT (INV-3): This server communicates EXCLUSIVELY over stdio.
4	/// No TCP socket. No UNIX socket listener. No UDP. Nothing.
5	/// If you need to add a debug interface, use a named pipe with strict file permissions
6	/// accessible only to the current user — never a network listener.
7	use anyhow::Result;
8	use serde::{Deserialize, Serialize};
9	use serde_json::Value;
10	use tokio::io::{AsyncBufReadExt, AsyncWriteExt, BufReader};
11	use tracing::{error, info, warn};
12	
13	use crate::tools;
14	
15	#[derive(Debug, Deserialize)]
16	struct JsonRpcRequest {
17	    jsonrpc: String,
18	    id: Option<Value>,
19	    method: String,
20	    #[serde(default)]
21	    params: Value,
22	}
23	
24	#[derive(Debug, Serialize)]
25	struct JsonRpcResponse {
26	    jsonrpc: String,
27	    id: Value,
28	    #[serde(skip_serializing_if = "Option::is_none")]
29	    result: Option<Value>,
30	    #[serde(skip_serializing_if = "Option::is_none")]
31	    error: Option<JsonRpcError>,
32	}
33	
34	#[derive(Debug, Serialize)]
35	struct JsonRpcError {
36	    code: i32,
37	    message: String,
38	    #[serde(skip_serializing_if = "Option::is_none")]
39	    data: Option<Value>,
40	}
41	
42	impl JsonRpcResponse {
43	    fn ok(id: Value, result: Value) -> Self {
44	        Self { jsonrpc: "2.0".into(), id, result: Some(result), error: None }
45	    }
46	
47	    fn err(id: Value, code: i32, message: impl Into<String>) -> Self {
48	        Self {
49	            jsonrpc: "2.0".into(),
50	            id,
51	            result: None,
52	            error: Some(JsonRpcError { code, message: message.into(), data: None }),
53	        }
54	    }
55	}
56	
57	pub async fn run_stdio_server() -> Result<()> {
58	    let stdin = tokio::io::stdin();
59	    let stdout = tokio::io::stdout();
60	    let mut reader = BufReader::new(stdin);
61	    let mut writer = stdout;
62	    let mut line = String::new();
63	
64	    info!("Listening on stdin for JSON-RPC requests");
65	
66	    loop {
67	        line.clear();
68	        let bytes_read = reader.read_line(&mut line).await?;
69	
70	        if bytes_read == 0 {
71	            info!("stdin closed — shutting down");
72	            break;
73	        }
74	
75	        let trimmed = line.trim();
76	        if trimmed.is_empty() {
77	            continue;
78	        }
79	
80	        let response = match serde_json::from_str::<JsonRpcRequest>(trimmed) {
81	            Err(e) => {
82	                warn!("Parse error: {}", e);
83	                JsonRpcResponse::err(Value::Null, -32700, format!("Parse error: {}", e))
84	            }
85	            Ok(req) => {
86	                if req.jsonrpc != "2.0" {
87	                    JsonRpcResponse::err(
88	                        req.id.unwrap_or(Value::Null),
89	                        -32600,
90	                        "Invalid Request: jsonrpc must be '2.0'",
91	                    )
92	                } else {
93	                    let id = req.id.clone().unwrap_or(Value::Null);
94	                    dispatch(req).await.unwrap_or_else(|e| {
95	                        error!("Dispatch error: {}", e);
96	                        JsonRpcResponse::err(id, -32603, format!("Internal error: {}", e))
97	                    })
98	                }
99	            }
100	        };
101	
102	        let mut response_str = serde_json::to_string(&response)?;
103	        response_str.push('\n');
104	        writer.write_all(response_str.as_bytes()).await?;
105	        writer.flush().await?;
106	    }
107	
108	    Ok(())
109	}
110	
111	async fn dispatch(req: JsonRpcRequest) -> Result<JsonRpcResponse> {
112	    let id = req.id.unwrap_or(Value::Null);
113	    info!("method={} id={}", req.method, id);
114	
115	    let result = match req.method.as_str() {
116	        // MCP discovery — returns the full tool catalogue
117	        "tools/list" => tools::list_all(),
118	
119	        // System read-only tools
120	        "system.status"  => tools::system::status().await,
121	        "system.uptime"  => tools::system::uptime().await,
122	        "system.cpu"     => tools::system::cpu().await,
123	        "system.memory"  => tools::system::memory().await,
124	        "system.disk"    => tools::system::disk().await,
125	
126	        // Process read-only tools
127	        "process.list"    => tools::process::list().await,
128	        "process.inspect" => {
129	            let pid = req.params.get("pid")
130	                .and_then(|v| v.as_u64())
131	                .ok_or_else(|| anyhow::anyhow!("Missing required param: pid (u64)"))?;
132	            tools::process::inspect(pid as u32).await
133	        }
134	
135	        // Unknown method
136	        method => {
137	            return Ok(JsonRpcResponse::err(
138	                id,
139	                -32601,
140	                format!("Method not found: {}", method),
141	            ));
142	        }
143	    };
144	
145	    match result {
146	        Ok(value) => Ok(JsonRpcResponse::ok(id, value)),
147	        Err(e) => Ok(JsonRpcResponse::err(id, -32603, e.to_string())),
148	    }
149	}
