10	pub async fn status() -> Result<Value> {
11	    let uptime_secs = read_uptime_secs()?;
12	    let mem = read_meminfo()?;
13	    let load = read_loadavg()?;
14	
15	    Ok(json!({
16	        "uptime_seconds": uptime_secs,
17	        "uptime_human": format_uptime(uptime_secs),
18	        "load_avg": load,
19	        "memory_mb": mem,
20	        "hostname": read_hostname().unwrap_or_else(|_| "unknown".into()),
21	    }))
22	}
