32	pub async fn cpu() -> Result<Value> {
33	    // Read /proc/stat for CPU utilization
34	    let stat1 = read_cpu_stat()?;
35	    // Brief sleep then read again to compute utilization delta
36	    tokio::time::sleep(Duration::from_millis(100)).await;
37	    let stat2 = read_cpu_stat()?;
38	
39	    let mut cores = Vec::new();
40	    for (s1, s2) in stat1.iter().zip(stat2.iter()) {
41	        let idle1 = s1.idle + s1.iowait;
42	        let idle2 = s2.idle + s2.iowait;
43	        let total1: u64 = s1.user + s1.nice + s1.system + s1.idle + s1.iowait + s1.irq + s1.softirq;
44	        let total2: u64 = s2.user + s2.nice + s2.system + s2.idle + s2.iowait + s2.irq + s2.softirq;
45	        let total_delta = total2.saturating_sub(total1);
46	        let idle_delta = idle2.saturating_sub(idle1);
47	        let usage = if total_delta == 0 {
48	            0.0
49	        } else {
50	            (1.0 - idle_delta as f64 / total_delta as f64) * 100.0
51	        };
52	        cores.push(json!({
53	            "name": s1.name,
54	            "usage_percent": (usage * 10.0).round() / 10.0,
55	        }));
56	    }
57	
58	    Ok(json!({ "cores": cores }))
59	}
