73	fn read_uptime_secs() -> Result<u64> {
74	    let content = fs::read_to_string("/proc/uptime")?;
75	    let secs: f64 = content
76	        .split_whitespace()
77	        .next()
78	        .ok_or_else(|| anyhow::anyhow!("Malformed /proc/uptime"))?
79	        .parse()?;
80	    Ok(secs as u64)
81	}
