83	fn format_uptime(secs: u64) -> String {
84	    let days = secs / 86400;
85	    let hours = (secs % 86400) / 3600;
86	    let mins = (secs % 3600) / 60;
87	    if days > 0 {
88	        format!("{}d {}h {}m", days, hours, mins)
89	    } else if hours > 0 {
90	        format!("{}h {}m", hours, mins)
91	    } else {
92	        format!("{}m", mins)
93	    }
94	}
