100	fn read_loadavg() -> Result<Value> {
101	    let content = fs::read_to_string("/proc/loadavg")?;
102	    let parts: Vec<&str> = content.split_whitespace().collect();
103	    Ok(json!({
104	        "1min":  parts.first().and_then(|s| s.parse::<f64>().ok()).unwrap_or(0.0),
105	        "5min":  parts.get(1).and_then(|s| s.parse::<f64>().ok()).unwrap_or(0.0),
106	        "15min": parts.get(2).and_then(|s| s.parse::<f64>().ok()).unwrap_or(0.0),
107	    }))
108	}
