110	fn read_meminfo() -> Result<Value> {
111	    let content = fs::read_to_string("/proc/meminfo")?;
112	    let mut map = std::collections::HashMap::new();
113	    for line in content.lines() {
114	        let parts: Vec<&str> = line.splitn(2, ':').collect();
115	        if parts.len() == 2 {
116	            let key = parts[0].trim();
117	            let val_kb: u64 = parts[1]
118	                .split_whitespace()
119	                .next()
120	                .and_then(|s| s.parse().ok())
121	                .unwrap_or(0);
122	            map.insert(key.to_string(), val_kb / 1024); // convert kB to MB
123	        }
124	    }
125	    Ok(json!({
126	        "total_mb":     map.get("MemTotal").copied().unwrap_or(0),
127	        "free_mb":      map.get("MemFree").copied().unwrap_or(0),
128	        "available_mb": map.get("MemAvailable").copied().unwrap_or(0),
129	        "cached_mb":    map.get("Cached").copied().unwrap_or(0),
130	        "swap_total_mb":map.get("SwapTotal").copied().unwrap_or(0),
131	        "swap_free_mb": map.get("SwapFree").copied().unwrap_or(0),
132	    }))
133	}
