136	struct CpuStat {
137	    name:    String,
138	    user:    u64,
139	    nice:    u64,
140	    system:  u64,
141	    idle:    u64,
142	    iowait:  u64,
143	    irq:     u64,
144	    softirq: u64,
145	}
