147	fn read_cpu_stat() -> Result<Vec<CpuStat>> {
148	    let content = fs::read_to_string("/proc/stat")?;
149	    let mut stats = Vec::new();
150	    for line in content.lines() {
151	        if !line.starts_with("cpu") {
152	            break;
153	        }
154	        let parts: Vec<&str> = line.split_whitespace().collect();
155	        if parts.len() < 8 {
156	            continue;
157	        }
158	        stats.push(CpuStat {
159	            name:    parts[0].to_string(),
160	            user:    parts[1].parse().unwrap_or(0),
161	            nice:    parts[2].parse().unwrap_or(0),
162	            system:  parts[3].parse().unwrap_or(0),
163	            idle:    parts[4].parse().unwrap_or(0),
164	            iowait:  parts[5].parse().unwrap_or(0),
165	            irq:     parts[6].parse().unwrap_or(0),
166	            softirq: parts[7].parse().unwrap_or(0),
167	        });
168	    }
169	    Ok(stats)
170	}
171	
172	fn read_mounts() -> Result<Vec<Value>> {
173	    let content = fs::read_to_string("/proc/mounts")?;
174	    let mut result = Vec::new();
175	    for line in content.lines() {
176	        let parts: Vec<&str> = line.split_whitespace().collect();
177	        if parts.len() < 3 {
178	            continue;
179	        }
180	        let mount_point = parts[1];
181	        // Skip pseudo-filesystems
182	        let fs_type = parts[2];
183	        if matches!(fs_type, "proc" | "sysfs" | "devtmpfs" | "cgroup" | "cgroup2"
184	            | "tmpfs" | "devpts" | "securityfs" | "debugfs" | "hugetlbfs"
185	            | "mqueue" | "fusectl" | "binfmt_misc") {
186	            continue;
187	        }
188	        // Try to get statvfs info
189	        if let Ok(stat) = nix_statvfs(mount_point) {
190	            result.push(stat);
191	        }
192	    }
193	    Ok(result)
194	}
195	
196	fn nix_statvfs(path: &str) -> Result<Value> {
197	    use std::ffi::CString;
198	    use std::mem;
199	
200	    let c_path = CString::new(path)?;
201	    let mut stat: libc::statvfs = unsafe { mem::zeroed() };
202	    let ret = unsafe { libc::statvfs(c_path.as_ptr(), &mut stat) };
203	    if ret != 0 {
204	        anyhow::bail!("statvfs failed for {}", path);
205	    }
206	    let block_size = stat.f_frsize as u64;
207	    let total_mb = (stat.f_blocks as u64) * block_size / 1_048_576;
208	    let free_mb = (stat.f_bfree as u64) * block_size / 1_048_576;
209	    let used_mb = total_mb.saturating_sub(free_mb);
210	    let used_pct = if total_mb == 0 { 0.0 } else { used_mb as f64 / total_mb as f64 * 100.0 };
211	    Ok(json!({
212	        "mount": path,
213	        "total_mb": total_mb,
214	        "used_mb": used_mb,
215	        "free_mb": free_mb,
216	        "used_percent": (used_pct * 10.0).round() / 10.0,
217	    }))
218	}
