1	/// process.rs — Read-only process inspection tools.
2	///
3	/// Reads from /proc only. No signals sent, no processes killed.
4	/// Tier 0 — auto-execute, no HITL prompt needed.
5	use anyhow::Result;
6	use serde_json::{json, Value};
7	use std::fs;
8	
9	pub async fn list() -> Result<Value> {
10	    let mut procs = Vec::new();
11	
12	    let proc_dir = fs::read_dir("/proc")?;
13	    for entry in proc_dir {
14	        let entry = entry?;
15	        let name = entry.file_name();
16	        let name_str = name.to_string_lossy();
17	
18	        // Only numeric directories are PIDs
19	        let pid: u32 = match name_str.parse() {
20	            Ok(n) => n,
21	            Err(_) => continue,
22	        };
23	
24	        if let Ok(info) = read_proc_info(pid) {
25	            procs.push(info);
26	        }
27	    }
28	
29	    // Sort by CPU usage descending
30	    procs.sort_by(|a, b| {
31	        let a_cpu = a["cpu_percent"].as_f64().unwrap_or(0.0);
32	        let b_cpu = b["cpu_percent"].as_f64().unwrap_or(0.0);
33	        b_cpu.partial_cmp(&a_cpu).unwrap_or(std::cmp::Ordering::Equal)
34	    });
35	
36	    Ok(json!({
37	        "count": procs.len(),
38	        "processes": procs,
39	    }))
40	}
