57	// ── Internal helpers ──────────────────────────────────────────────────────────
58	
59	fn read_proc_info(pid: u32) -> Result<Value> {
60	    let stat_path = format!("/proc/{}/stat", pid);
61	    let content = fs::read_to_string(&stat_path)?;
62	
63	    // /proc/PID/stat format:
64	    // pid (comm) state ppid pgroup session ...
65	    // comm can contain spaces and parens, so parse carefully
66	    let comm_start = content.find('(').ok_or_else(|| anyhow::anyhow!("Malformed stat"))?;
67	    let comm_end = content.rfind(')').ok_or_else(|| anyhow::anyhow!("Malformed stat"))?;
68	    let comm = &content[comm_start + 1..comm_end];
69	    let rest: Vec<&str> = content[comm_end + 2..].split_whitespace().collect();
70	
71	    let state = rest.first().copied().unwrap_or("?");
72	    let ppid: u32 = rest.get(1).and_then(|s| s.parse().ok()).unwrap_or(0);
73	    // utime is field 11 (0-indexed from rest), stime is field 12
74	    let utime: u64 = rest.get(11).and_then(|s| s.parse().ok()).unwrap_or(0);
75	    let stime: u64 = rest.get(12).and_then(|s| s.parse().ok()).unwrap_or(0);
76	    let vsize_bytes: u64 = rest.get(20).and_then(|s| s.parse().ok()).unwrap_or(0);
77	    let rss_pages: i64 = rest.get(21).and_then(|s| s.parse().ok()).unwrap_or(0);
78	
79	    let page_size = unsafe { libc::sysconf(libc::_SC_PAGESIZE) } as u64;
80	    let rss_mb = (rss_pages.max(0) as u64 * page_size) / 1_048_576;
81	    let vsize_mb = vsize_bytes / 1_048_576;
82	
83	    // Rough CPU % (total ticks / uptime — not perfectly accurate but good enough)
84	    let ticks_per_sec = unsafe { libc::sysconf(libc::_SC_CLK_TCK) } as f64;
85	    let uptime_secs = fs::read_to_string("/proc/uptime")
86	        .ok()
87	        .and_then(|s| s.split_whitespace().next().and_then(|v| v.parse::<f64>().ok()))
88	        .unwrap_or(1.0);
89	    let total_ticks = (utime + stime) as f64;
90	    let cpu_pct = (total_ticks / ticks_per_sec / uptime_secs * 100.0 * 10.0).round() / 10.0;
91	
92	    Ok(json!({
93	        "pid": pid,
94	        "name": comm,
95	        "state": state,
96	        "ppid": ppid,
97	        "cpu_percent": cpu_pct,
98	        "rss_mb": rss_mb,
99	        "vsize_mb": vsize_mb,
100	    }))
101	}
102	
103	fn read_cmdline(pid: u32) -> Result<String> {
104	    let path = format!("/proc/{}/cmdline", pid);
105	    let bytes = fs::read(&path)?;
106	    // cmdline is null-separated
107	    Ok(bytes
108	        .split(|&b| b == 0)
109	        .filter(|s| !s.is_empty())
110	        .map(|s| String::from_utf8_lossy(s).into_owned())
111	        .collect::<Vec<_>>()
112	        .join(" "))
113	}
114	
115	fn read_status(pid: u32) -> Result<Value> {
116	    let path = format!("/proc/{}/status", pid);
117	    let content = fs::read_to_string(&path)?;
118	    let mut map = serde_json::Map::new();
119	    for line in content.lines() {
120	        let parts: Vec<&str> = line.splitn(2, ':').collect();
121	        if parts.len() == 2 {
122	            map.insert(
123	                parts[0].trim().to_lowercase(),
124	                Value::String(parts[1].trim().to_string()),
125	            );
126	        }
127	    }
128	    Ok(Value::Object(map))
